    public QuoteService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new QuoteEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(QuoteRepository.class) );
		this.validator		= applicationContext.getBean(QuoteValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Quote
	 */
		public Quote createQuote( CreateQuoteCommand command ) {

		Quote entity = new Quote();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setQuoteId( command.getQuoteId() );
            entity.setQuoteNumber( command.getQuoteNumber() );
            entity.setValidityStart( command.getValidityStart() );
            entity.setValidityEnd( command.getValidityEnd() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setDiscountPercent( command.getDiscountPercent() );
            entity.setTaxAmount( command.getTaxAmount() );
            entity.setShippingAmount( command.getShippingAmount() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Quote {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateQuoteCommand
	 * @return		Quote
	 */
	public Quote updateQuote( UpdateQuoteCommand command ) {

		Quote entity = new Quote();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setQuoteId( command.getQuoteId() );
            entity.setQuoteNumber( command.getQuoteNumber() );
            entity.setValidityStart( command.getValidityStart() );
            entity.setValidityEnd( command.getValidityEnd() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setDiscountPercent( command.getDiscountPercent() );
            entity.setTaxAmount( command.getTaxAmount() );
            entity.setShippingAmount( command.getShippingAmount() );
            entity.setOrganization( command.getOrganization() );
            entity.setAccount( command.getAccount() );
            entity.setOpportunity( command.getOpportunity() );
            entity.setOwner( command.getOwner() );
            entity.setLineItems( command.getLineItems() );
            entity.setPriceBook( command.getPriceBook() );
            entity.setOrder( command.getOrder() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Quote {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteQuoteCommand
	 */
	public void delete( DeleteQuoteCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getQuoteId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Quote {0} ", id );

	}

	/**
	 * Method to retrieve the Quote via QuoteFetchOneSummary
	 * @param 	summary QuoteFetchOneSummary
	 * @return 	QuoteFetchOneResponse
	 */
	public Quote getQuote( QuoteFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "QuoteFetchOneSummary arg cannot be null" );

		Quote entity = null;
		UUID id = summary.getQuoteId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Quote using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Quotes
	 *
	 * @return 	List<Quote>
	 */
    public List<Quote> getAllQuote() {
		List<Quote> list = projector.findAll( new FindAllQuoteQuery() );
		return list;
	}

